			// Shadow branch has files from carry-forward - check if staged files overlap
			// AND have matching content (content-aware check).
			stagedFiles := getStagedFiles(repo)
			result := stagedFilesOverlapWithContent(repo, tree, stagedFiles, state.FilesTouched)
			return result, nil
		}
		// No transcript and no FilesTouched - fall back to live transcript check
		return s.sessionHasNewContentFromLiveTranscript(repo, state)
	}

	// Has new content if there are more lines than already condensed.
	// However, even if transcript has grown, we need to verify that the staged files
	// actually contain session content. If the user reverted the agent's changes and
	// wrote completely different content, we should NOT add a checkpoint trailer.
	// This is the "content-aware overlap detection" for the reverted-and-replaced scenario.
	if transcriptLines <= state.CheckpointTranscriptStart {
		return false, nil // No new transcript content
	}

	// Transcript has grown - now check if staged files overlap with session's files
	// AND have matching content. If user reverted and replaced, content won't match.
	if len(state.FilesTouched) > 0 {
		stagedFiles := getStagedFiles(repo)
		if len(stagedFiles) > 0 {
			// Use content-aware overlap check
			return stagedFilesOverlapWithContent(repo, tree, stagedFiles, state.FilesTouched), nil
		}
		// No staged files, but transcript has content - this shouldn't happen in normal flow
		// (user is committing something, so there should be staged files)
		return true, nil // Fall back to assuming new content
	}

	// No FilesTouched tracked but transcript has content - session likely didn't modify files
	return true, nil
}
